import sys

data = sys.stdin.read().split()
n = int(data[0])
P = [(int(data[1 + 2 * i]), int(data[2 + 2 * i])) for i in range(n)]
best = -1
for mask in range(1, (1 << n) - 1):
    f = None
    for i in range(n):
        for j in range(i + 1, n):
            if (mask >> i & 1) == (mask >> j & 1):
                d = abs(P[i][0] - P[j][0]) + abs(P[i][1] - P[j][1])
                if f is None or d < f:
                    f = d
    if f is not None and f > best:
        best = f
print(best)

